// Package controllers exposes HTTP endpoints for the webhooks bounded context.
package controllers

import (
	"crypto/sha256"
	"encoding/hex"
	"io"
	"net/http"

	wire "template/contracts-go/wire"
	"template/api-go/internal/sync/enums"
	ctxerrors "template/api-go/internal/webhooks/errors"
	"template/api-go/internal/webhooks/services"
	"template/core-go/objects"
	coreerrors "template/core-go/errors"
	corerepos "template/core-go/repositories"
	"template/core-go/pkg/httputil"
	"template/core-go/types"
)

// WebhookRequest is the fully decoded + validated intake for POST /webhooks.
// All four query params are required; oneof= gates on the closed enums so an
// invalid platform or event value is rejected at decode time (HTTP 400).
type WebhookRequest struct {
	Platform      enums.WebhookPlatform `from:"query" name:"platform"      validate:"required,oneof=SHOPIFY NUVEM_SHOP META TIKTOK GOOGLE_ADS"`
	Event         wire.SyncEventName    `from:"query" name:"event"         validate:"required,oneof=sync.external_order_updated sync.external_product_updated sync.external_product_variant_updated sync.external_transaction_updated"`
	IntegrationID string                `from:"query" name:"integrationId" validate:"required"`
	StoreID       string                `from:"query" name:"storeId"       validate:"required"`
}

// WebhookAcceptedResponse is the 202 body returned on successful intake.
type WebhookAcceptedResponse struct {
	Status          string             `json:"status"`
	ExternalEventID string             `json:"externalEventId"`
	Event           wire.SyncEventName `json:"event"`
}

// WebhookController is the single inbound webhook endpoint. It verifies
// the per-platform signature, then publishes a WebhookReceivedEvent
// (deduped by sha256(rawBody)). The WebhookReceivedEventHandler maps it
// into sync.ExternalXUpdatedEvent(s) downstream.
//
// URL: POST /webhooks?platform&event&integrationId&storeId
// All four query params are required; missing or invalid → 400.
type WebhookController struct {
	verifiers *services.WebhookVerifierFactory
	events    corerepos.DomainEventRepository
}

// NewWebhookController constructs the single webhook intake controller.
func NewWebhookController(
	verifiers *services.WebhookVerifierFactory,
	events corerepos.DomainEventRepository,
) *WebhookController {
	return &WebhookController{verifiers: verifiers, events: events}
}

func (c *WebhookController) Metadata() types.ControllerMetadata {
	return types.ControllerMetadata{
		Context:     "webhooks",
		Path:        "/webhooks",
		Method:      http.MethodPost,
		Description: "Inbound provider webhook intake — verify signature + publish WebhookReceivedEvent. ?platform&event&integrationId&storeId",
		Tags:        []string{"webhooks"},
		Request:     WebhookRequest{},
		Response:    WebhookAcceptedResponse{},
		Status:      http.StatusAccepted,
		Errors: []coreerrors.ErrorCode{
			ctxerrors.CodeMissingWebhookParams,
			ctxerrors.CodeUnknownPlatform,
			ctxerrors.CodeInvalidSignature,
		},
	}
}

func (c *WebhookController) Handle(w http.ResponseWriter, r *http.Request) {
	if r.URL.Query().Get("type") == "PIXEL_EVENT" {
		c.handlePixel(w, r)
		return
	}

	req, err := httputil.DecodeRequest[WebhookRequest](r)
	if err != nil {
		httputil.RespondError(w, err)
		return
	}

	verifier, ok := c.verifiers.Get(req.Platform)
	if !ok {
		httputil.RespondError(w, coreerrors.NewBaseError(ctxerrors.CodeUnknownPlatform,
			"unknown platform: "+string(req.Platform)))
		return
	}

	body, err := io.ReadAll(r.Body)
	if err != nil {
		httputil.RespondError(w, coreerrors.NewBaseError(coreerrors.CodeBadRequest, err.Error()))
		return
	}
	defer r.Body.Close()

	valid, err := verifier.Verify(body, r.Header.Get(verifier.SignatureHeader()))
	if err != nil || !valid {
		httputil.RespondError(w, coreerrors.NewBaseError(ctxerrors.CodeInvalidSignature, "invalid signature"))
		return
	}

	sum := sha256.Sum256(body)
	externalEventID := hex.EncodeToString(sum[:])

	id, err := objects.IDFromSeed("webhook", string(req.Platform), externalEventID)
	if err != nil {
		httputil.RespondError(w, coreerrors.NewBaseError(coreerrors.CodeDatabaseError, err.Error()))
		return
	}

	received := types.NewDomainEvent(
		services.WebhookReceivedEventName,
		id.UUID(),
		"", // ownerID resolved downstream by the per-entity handler
		services.WebhookReceivedPayload{
			Platform:        req.Platform,
			Event:           req.Event,
			IntegrationID:   req.IntegrationID,
			StoreID:         req.StoreID,
			ExternalEventID: externalEventID,
			RawBody:         string(body),
		},
	)

	if err := c.events.Save(r.Context(), received); err != nil {
		httputil.RespondError(w, err)
		return
	}

	httputil.RespondJSON(w, http.StatusAccepted, WebhookAcceptedResponse{
		Status:          "accepted",
		ExternalEventID: externalEventID,
		Event:           req.Event,
	})
}

// handlePixel accepts browser-origin Shopify Web Pixel events. Unlike provider
// webhooks these are UNSIGNED (no HMAC). The browser asserts only platform +
// storeIntegrationId (the sales-channel id the pixel bundle embeds); storeId is
// resolved server-side downstream (never client-supplied). The event is fixed to
// sync.external_pixel_event_recorded; the body's pixel sub-type is read by the mapper.
func (c *WebhookController) handlePixel(w http.ResponseWriter, r *http.Request) {
	platform := r.URL.Query().Get("platform")
	storeIntegrationID := r.URL.Query().Get("storeIntegrationId")
	if platform == "" || storeIntegrationID == "" {
		httputil.RespondError(w, coreerrors.NewBaseError(ctxerrors.CodeMissingWebhookParams,
			"pixel intake requires platform + storeIntegrationId"))
		return
	}

	body, err := io.ReadAll(r.Body)
	if err != nil {
		httputil.RespondError(w, coreerrors.NewBaseError(coreerrors.CodeBadRequest, err.Error()))
		return
	}
	defer r.Body.Close()

	sum := sha256.Sum256(body)
	externalEventID := hex.EncodeToString(sum[:])

	id, err := objects.IDFromSeed("pixel-intake", platform, externalEventID)
	if err != nil {
		httputil.RespondError(w, coreerrors.NewBaseError(coreerrors.CodeDatabaseError, err.Error()))
		return
	}

	received := types.NewDomainEvent(
		services.WebhookReceivedEventName,
		id.UUID(),
		"", // ownerID resolved downstream by the pixel handler
		services.WebhookReceivedPayload{
			Platform:        enums.WebhookPlatform(platform),
			Event:           wire.SyncEventNameEXTERNAL_PIXEL_EVENT_RECORDED,
			IntegrationID:   storeIntegrationID,
			StoreID:         "", // never trusted from the client; resolved server-side
			ExternalEventID: externalEventID,
			RawBody:         string(body),
		},
	)

	if err := c.events.Save(r.Context(), received); err != nil {
		httputil.RespondError(w, err)
		return
	}

	httputil.RespondJSON(w, http.StatusAccepted, WebhookAcceptedResponse{
		Status:          "accepted",
		ExternalEventID: externalEventID,
		Event:           wire.SyncEventNameEXTERNAL_PIXEL_EVENT_RECORDED,
	})
}

package services

import "template/api-go/internal/sync/enums"

// WebhookVerifierFactory is a platform-keyed resolver for webhook signature
// verifiers. Adding a new provider = register its Verifier against the
// platform enum. Returns nil + false for unregistered platforms — the
// controller maps that to HTTP 400 Unknown Platform without panicking.
type WebhookVerifierFactory struct {
	verifiers map[enums.WebhookPlatform]WebhookVerifier
}

func NewWebhookVerifierFactory(verifiers []WebhookVerifier) *WebhookVerifierFactory {
	m := map[enums.WebhookPlatform]WebhookVerifier{}
	for _, v := range verifiers {
		m[v.Platform()] = v
	}
	return &WebhookVerifierFactory{verifiers: m}
}

func (f *WebhookVerifierFactory) Get(platform enums.WebhookPlatform) (WebhookVerifier, bool) {
	v, ok := f.verifiers[platform]
	return v, ok
}

package services

import "template/api-go/internal/sync/enums"

// WebhookVerifier validates a provider's signed webhook payload. Returns
// (true, nil) on a valid signature, (false, nil) on an invalid one, and
// (_, err) only for transport-level failures (e.g. missing decode key).
// One impl per provider — the Factory dispatches by platform.
type WebhookVerifier interface {
	Platform() enums.WebhookPlatform
	SignatureHeader() string
	Verify(rawBody []byte, signature string) (bool, error)
}

package enums

import "fmt"

// WebhookPlatform is the closed set of providers the webhook intake accepts.
// Canonical spelling is the underscore form, matching wire.SalesPlatform /
// wire.CheckoutPlatform.
type WebhookPlatform string

const (
	WebhookPlatformShopify   WebhookPlatform = "SHOPIFY"
	WebhookPlatformNuvemShop WebhookPlatform = "NUVEM_SHOP"
	WebhookPlatformMeta      WebhookPlatform = "META"
	WebhookPlatformTikTok    WebhookPlatform = "TIKTOK"
	WebhookPlatformGoogleAds WebhookPlatform = "GOOGLE_ADS"
)

func (p WebhookPlatform) Valid() bool {
	switch p {
	case WebhookPlatformShopify, WebhookPlatformNuvemShop,
		WebhookPlatformMeta, WebhookPlatformTikTok, WebhookPlatformGoogleAds:
		return true
	}
	return false
}

func ParseWebhookPlatform(s string) (WebhookPlatform, error) {
	p := WebhookPlatform(s)
	if !p.Valid() {
		return "", fmt.Errorf("invalid WebhookPlatform: %q", s)
	}
	return p, nil
}

// WebhookPlatformOneof is the space-separated value list for validator/v10 `oneof=`.
const WebhookPlatformOneof = "SHOPIFY NUVEM_SHOP META TIKTOK GOOGLE_ADS"

package httputil

import (
	"encoding/json"
	"net/http"
	"reflect"
	"strconv"
	"strings"

	"template/core-go/errors"
	"template/core-go/pkg/validation"
)

// DecodeRequest decodes an HTTP request into a struct that defines the full request schema.
// The struct should have fields tagged with `from:"body"`, `from:"param"`, `from:"query"`,
// `from:"header"`, or `from:"cookie"` to indicate where each field comes from.
//
// Fields tagged with `from:"body"` are decoded from the JSON request body.
// Fields tagged with `from:"param"` are read from path parameters via r.PathValue().
// Fields tagged with `from:"query"` are read from query string parameters.
// Fields tagged with `from:"header"` are read from request headers.
// Fields tagged with `from:"cookie"` are read from HTTP cookies.
//
// The `json` tag is used for body field names, and `name` tag for param/query/header/cookie names.
// After decoding, the struct is validated using validator/v10 tags.
//
// Example:
//
//	type CreateTodoRequest struct {
//	    OwnerID string `from:"cookie" name:"owner_id" validate:"required" swaggerignore:"true"`
//	    Title    string `from:"body"   json:"title"     validate:"required,min=1,max=255" example:"Buy groceries"`
//	}
//
//	type CompleteTodoRequest struct {
//	    ID string `from:"param" name:"id" validate:"required,uuid" example:"7c9e..."`
//	}
//
//	type ListTodosRequest struct {
//	    OwnerID string `from:"cookie" name:"owner_id" validate:"required" swaggerignore:"true"`
//	    Limit    int    `from:"query"  name:"limit"     validate:"omitempty,min=1,max=100"`
//	    Offset   int    `from:"query"  name:"offset"    validate:"omitempty,min=0"`
//	}
func DecodeRequest[T any](r *http.Request) (T, error) {
	var input T
	val := reflect.ValueOf(&input).Elem()
	typ := val.Type()

	var hasBody bool

	// First pass: check if there are any body fields
	for i := 0; i < typ.NumField(); i++ {
		if typ.Field(i).Tag.Get("from") == "body" {
			hasBody = true
			break
		}
	}

	// Decode body fields from JSON
	if hasBody && r.Body != nil {
		bodyMap := make(map[string]json.RawMessage)
		if err := json.NewDecoder(r.Body).Decode(&bodyMap); err != nil {
			return input, errors.NewBaseError(errors.CodeBadRequest, "invalid request body: "+err.Error())
		}

		for i := 0; i < typ.NumField(); i++ {
			field := typ.Field(i)
			if field.Tag.Get("from") != "body" {
				continue
			}

			// Standard Go json tag semantics: the tag can carry options after
			// the name separated by commas (e.g. `json:"foo,omitempty"`). Only
			// the first segment is the actual field name — split it off so
			// optional pointer fields decode correctly.
			jsonTag := field.Tag.Get("json")
			jsonName, _, _ := strings.Cut(jsonTag, ",")
			if jsonName == "" || jsonName == "-" {
				jsonName = field.Name
			}

			raw, ok := bodyMap[jsonName]
			if !ok {
				continue
			}

			fieldVal := val.Field(i)
			if fieldVal.CanSet() {
				ptr := reflect.New(field.Type)
				if err := json.Unmarshal(raw, ptr.Interface()); err != nil {
					return input, errors.NewBaseError(errors.CodeBadRequest, "invalid field "+jsonName+": "+err.Error())
				}
				fieldVal.Set(ptr.Elem())
			}
		}
	}

	// Decode param, query, header, and ctx fields
	for i := 0; i < typ.NumField(); i++ {
		field := typ.Field(i)
		from := field.Tag.Get("from")
		name := field.Tag.Get("name")
		if name == "" {
			name = field.Name
		}

		var strValue string

		switch from {
		case "param":
			strValue = r.PathValue(name)
		case "query":
			strValue = r.URL.Query().Get(name)
		case "header":
			strValue = r.Header.Get(name)
		case "cookie":
			if c, err := r.Cookie(name); err == nil {
				strValue = c.Value
			}
		default:
			continue
		}

		if strValue == "" {
			continue
		}

		fieldVal := val.Field(i)
		if !fieldVal.CanSet() {
			continue
		}

		switch field.Type.Kind() {
		case reflect.String:
			fieldVal.SetString(strValue)
		case reflect.Int, reflect.Int64:
			if n, err := strconv.ParseInt(strValue, 10, 64); err == nil {
				fieldVal.SetInt(n)
			}
		case reflect.Bool:
			if b, err := strconv.ParseBool(strValue); err == nil {
				fieldVal.SetBool(b)
			}
		case reflect.Float64:
			if f, err := strconv.ParseFloat(strValue, 64); err == nil {
				fieldVal.SetFloat(f)
			}
		}
	}

	// Validate the fully decoded struct
	if err := validation.Validate(&input); err != nil {
		return input, err
	}

	return input, nil
}

