package controllers

import (
	"bytes"
	"context"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"testing"

	wire "template/contracts-go/wire"
	"template/api-go/internal/sync/enums"
	"template/api-go/internal/webhooks/services"
	"template/core-go/types"
)

// fakeVerifier is a test double implementing services.WebhookVerifier.
type fakeVerifier struct{ valid bool }

func (f fakeVerifier) Platform() enums.WebhookPlatform             { return enums.WebhookPlatformShopify }
func (f fakeVerifier) SignatureHeader() string                      { return "X-Sig" }
func (f fakeVerifier) Verify(_ []byte, _ string) (bool, error)     { return f.valid, nil }

// fakeEventRepo records domain events saved to it.
type fakeEventRepo struct{ saved []types.DomainEventI }

func (r *fakeEventRepo) Save(_ context.Context, e types.DomainEventI) error {
	r.saved = append(r.saved, e)
	return nil
}
func (r *fakeEventRepo) SaveAll(_ context.Context, es []types.DomainEventI) error {
	r.saved = append(r.saved, es...)
	return nil
}

func buildController(valid bool) (*WebhookController, *fakeEventRepo) {
	repo := &fakeEventRepo{}
	factory := services.NewWebhookVerifierFactory([]services.WebhookVerifier{
		fakeVerifier{valid: valid},
	})
	ctrl := NewWebhookController(factory, repo)
	return ctrl, repo
}

func fireRequest(ctrl *WebhookController, query string, body string) *httptest.ResponseRecorder {
	req := httptest.NewRequest(http.MethodPost, "/webhooks?"+query, bytes.NewBufferString(body))
	w := httptest.NewRecorder()
	ctrl.Handle(w, req)
	return w
}

// TestWebhookController_MissingPlatform — missing platform → 400, no save
func TestWebhookController_MissingPlatform(t *testing.T) {
	ctrl, repo := buildController(true)
	w := fireRequest(ctrl, "event=sync.external_order_updated&integrationId=int-1&storeId=store-1", "{}")
	if w.Code != http.StatusBadRequest {
		t.Errorf("status = %d, want 400", w.Code)
	}
	if len(repo.saved) != 0 {
		t.Errorf("saved = %d, want 0", len(repo.saved))
	}
}

// TestWebhookController_MissingEvent — missing event → 400, no save
func TestWebhookController_MissingEvent(t *testing.T) {
	ctrl, repo := buildController(true)
	w := fireRequest(ctrl, "platform=SHOPIFY&integrationId=int-1&storeId=store-1", "{}")
	if w.Code != http.StatusBadRequest {
		t.Errorf("status = %d, want 400", w.Code)
	}
	if len(repo.saved) != 0 {
		t.Errorf("saved = %d, want 0", len(repo.saved))
	}
}

// TestWebhookController_MissingIntegrationID — missing integrationId → 400, no save
func TestWebhookController_MissingIntegrationID(t *testing.T) {
	ctrl, repo := buildController(true)
	w := fireRequest(ctrl, "platform=SHOPIFY&event=sync.external_order_updated&storeId=store-1", "{}")
	if w.Code != http.StatusBadRequest {
		t.Errorf("status = %d, want 400", w.Code)
	}
	if len(repo.saved) != 0 {
		t.Errorf("saved = %d, want 0", len(repo.saved))
	}
}

// TestWebhookController_MissingStoreID — missing storeId → 400, no save
func TestWebhookController_MissingStoreID(t *testing.T) {
	ctrl, repo := buildController(true)
	w := fireRequest(ctrl, "platform=SHOPIFY&event=sync.external_order_updated&integrationId=int-1", "{}")
	if w.Code != http.StatusBadRequest {
		t.Errorf("status = %d, want 400", w.Code)
	}
	if len(repo.saved) != 0 {
		t.Errorf("saved = %d, want 0", len(repo.saved))
	}
}

// TestWebhookController_UnknownPlatform — platform not registered in verifier factory → 400
func TestWebhookController_UnknownPlatform(t *testing.T) {
	ctrl, repo := buildController(true)
	w := fireRequest(ctrl, "platform=META&event=sync.external_order_updated&integrationId=int-1&storeId=store-1", "{}")
	if w.Code != http.StatusBadRequest {
		t.Errorf("status = %d, want 400", w.Code)
	}
	if len(repo.saved) != 0 {
		t.Errorf("saved = %d, want 0", len(repo.saved))
	}
}

// TestWebhookController_InvalidSignature — invalid sig → 401, no save
func TestWebhookController_InvalidSignature(t *testing.T) {
	ctrl, repo := buildController(false) // verifier returns !valid
	w := fireRequest(ctrl, "platform=SHOPIFY&event=sync.external_order_updated&integrationId=int-1&storeId=store-1", "{}")
	if w.Code != http.StatusUnauthorized {
		t.Errorf("status = %d, want 401", w.Code)
	}
	if len(repo.saved) != 0 {
		t.Errorf("saved = %d, want 0", len(repo.saved))
	}
}

// TestWebhook_InvalidEvent400 — bogus event value rejected before any save
func TestWebhook_InvalidEvent400(t *testing.T) {
	ctrl, repo := buildController(true)
	w := fireRequest(ctrl, "platform=SHOPIFY&event=bogus&integrationId=int-1&storeId=store-1", "{}")
	if w.Code != http.StatusBadRequest {
		t.Errorf("status = %d, want 400 for invalid event", w.Code)
	}
	if len(repo.saved) != 0 {
		t.Errorf("saved = %d, want 0", len(repo.saved))
	}
}

// TestWebhook_InvalidPlatform400 — bogus platform value rejected at decode
func TestWebhook_InvalidPlatform400(t *testing.T) {
	ctrl, repo := buildController(true)
	w := fireRequest(ctrl, "platform=UNKNOWN&event=sync.external_order_updated&integrationId=int-1&storeId=store-1", "{}")
	if w.Code != http.StatusBadRequest {
		t.Errorf("status = %d, want 400 for invalid platform", w.Code)
	}
	if len(repo.saved) != 0 {
		t.Errorf("saved = %d, want 0", len(repo.saved))
	}
}

// TestWebhookController_Verified — valid sig → 202, exactly 1 event saved with correct fields + deterministic id
func TestWebhookController_Verified(t *testing.T) {
	ctrl, repo := buildController(true)
	body := `{"order":"data"}`
	w := fireRequest(ctrl, "platform=SHOPIFY&event=sync.external_order_updated&integrationId=int-1&storeId=store-1", body)
	if w.Code != http.StatusAccepted {
		t.Errorf("status = %d, want 202", w.Code)
	}
	if len(repo.saved) != 1 {
		t.Fatalf("saved = %d, want 1", len(repo.saved))
	}
	evt, ok := repo.saved[0].(services.WebhookReceivedEvent)
	if !ok {
		t.Fatalf("saved event type = %T, want WebhookReceivedEvent", repo.saved[0])
	}
	if evt.Payload.Platform != enums.WebhookPlatformShopify {
		t.Errorf("Platform = %q, want %q", evt.Payload.Platform, enums.WebhookPlatformShopify)
	}
