// Package controllers exposes HTTP endpoints for the webhooks bounded context.
package controllers

import (
	"crypto/sha256"
	"encoding/hex"
	"io"
	"net/http"

	"template/api-go/internal/sync/enums"
	ctxerrors "template/api-go/internal/webhooks/errors"
	"template/api-go/internal/webhooks/services"
	wire "template/contracts-go/wire"
	coreerrors "template/core-go/errors"
	"template/core-go/objects"
	"template/core-go/pkg/httputil"
	corerepos "template/core-go/repositories"
	"template/core-go/types"
)

// WebhookRequest is the fully decoded + validated intake for POST /webhooks.
// All four query params are required; oneof= gates on the closed enums so an
// invalid platform or event value is rejected at decode time (HTTP 400).
type WebhookRequest struct {
	Platform      enums.WebhookPlatform `from:"query" name:"platform"      validate:"required,oneof=SHOPIFY NUVEM_SHOP META TIKTOK GOOGLE_ADS"`
	Event         wire.SyncEventName    `from:"query" name:"event"         validate:"required,oneof=sync.external_order_updated sync.external_product_updated sync.external_product_variant_updated sync.external_transaction_updated sync.external_pixel_event_recorded"`
	IntegrationID string                `from:"query" name:"integrationId" validate:"required"`
	StoreID       string                `from:"query" name:"storeId"       validate:"required"`
}

// WebhookAcceptedResponse is the 202 body returned on successful intake.
type WebhookAcceptedResponse struct {
	Status          string             `json:"status"`
	ExternalEventID string             `json:"externalEventId"`
	Event           wire.SyncEventName `json:"event"`
}

// WebhookController is the single inbound webhook endpoint. It verifies
// the per-platform signature, then publishes a WebhookReceivedEvent
// (deduped by sha256(rawBody)). The WebhookReceivedEventHandler maps it
// into sync.ExternalXUpdatedEvent(s) downstream.
//
// URL: POST /webhooks?platform&event&integrationId&storeId
// All four query params are required; missing or invalid → 400.
type WebhookController struct {
	verifiers *services.WebhookVerifierFactory
	events    corerepos.DomainEventRepository
}

// NewWebhookController constructs the single webhook intake controller.
func NewWebhookController(
	verifiers *services.WebhookVerifierFactory,
	events corerepos.DomainEventRepository,
) *WebhookController {
	return &WebhookController{verifiers: verifiers, events: events}
}

func (c *WebhookController) Metadata() types.ControllerMetadata {
	return types.ControllerMetadata{
		Context:     "webhooks",
		Path:        "/webhooks",
		Method:      http.MethodPost,
		Description: "Inbound provider webhook intake — verify signature + publish WebhookReceivedEvent. ?platform&event&integrationId&storeId",
		Tags:        []string{"webhooks"},
		Request:     WebhookRequest{},
		Response:    WebhookAcceptedResponse{},
		Status:      http.StatusAccepted,
		Errors: []coreerrors.ErrorCode{
			ctxerrors.CodeMissingWebhookParams,
			ctxerrors.CodeUnknownPlatform,
			ctxerrors.CodeInvalidSignature,
		},
	}
}

func (c *WebhookController) Handle(w http.ResponseWriter, r *http.Request) {
	if r.URL.Query().Get("type") == "PIXEL_EVENT" {
		c.handlePixel(w, r)
		return
	}

	req, err := httputil.DecodeRequest[WebhookRequest](r)
	if err != nil {
		httputil.RespondError(w, err)
		return
	}

	verifier, ok := c.verifiers.Get(req.Platform)
	if !ok {
		httputil.RespondError(w, coreerrors.NewBaseError(ctxerrors.CodeUnknownPlatform,
			"unknown platform: "+string(req.Platform)))
		return
	}

	body, err := io.ReadAll(r.Body)
	if err != nil {
		httputil.RespondError(w, coreerrors.NewBaseError(coreerrors.CodeBadRequest, err.Error()))
		return
	}
	defer r.Body.Close()

	valid, err := verifier.Verify(body, r.Header.Get(verifier.SignatureHeader()))
	if err != nil || !valid {
		httputil.RespondError(w, coreerrors.NewBaseError(ctxerrors.CodeInvalidSignature, "invalid signature"))
		return
	}

	sum := sha256.Sum256(body)
	externalEventID := hex.EncodeToString(sum[:])

	id, err := objects.IDFromSeed("webhook", string(req.Platform), externalEventID)
	if err != nil {
		httputil.RespondError(w, coreerrors.NewBaseError(coreerrors.CodeDatabaseError, err.Error()))
		return
	}

	received := types.NewDomainEvent(
		services.WebhookReceivedEventName,
		id.UUID(),
		"", // ownerID resolved downstream by the per-entity handler
		services.WebhookReceivedPayload{
			Platform:        req.Platform,
			Event:           req.Event,
			IntegrationID:   req.IntegrationID,
			StoreID:         req.StoreID,
			ExternalEventID: externalEventID,
			RawBody:         string(body),
		},
	)

	if err := c.events.Save(r.Context(), received); err != nil {
		httputil.RespondError(w, err)
		return
	}

	httputil.RespondJSON(w, http.StatusAccepted, WebhookAcceptedResponse{
		Status:          "accepted",
		ExternalEventID: externalEventID,
		Event:           req.Event,
	})
}

// handlePixel accepts browser-origin Shopify Web Pixel events. Unlike provider
// webhooks these are UNSIGNED (no HMAC). The browser asserts only platform +
// storeIntegrationId (the sales-channel id the pixel bundle embeds); storeId is
// resolved server-side downstream (never client-supplied). The event is fixed to
// sync.external_pixel_event_recorded; the body's pixel sub-type is read by the mapper.
func (c *WebhookController) handlePixel(w http.ResponseWriter, r *http.Request) {
	platform := r.URL.Query().Get("platform")
	storeIntegrationID := r.URL.Query().Get("storeIntegrationId")
	if platform == "" || storeIntegrationID == "" {
		httputil.RespondError(w, coreerrors.NewBaseError(ctxerrors.CodeMissingWebhookParams,
			"pixel intake requires platform + storeIntegrationId"))
		return
	}

	body, err := io.ReadAll(r.Body)
	if err != nil {
		httputil.RespondError(w, coreerrors.NewBaseError(coreerrors.CodeBadRequest, err.Error()))
		return
	}
	defer r.Body.Close()

	sum := sha256.Sum256(body)
	externalEventID := hex.EncodeToString(sum[:])

	id, err := objects.IDFromSeed("pixel-intake", platform, externalEventID)
	if err != nil {
		httputil.RespondError(w, coreerrors.NewBaseError(coreerrors.CodeDatabaseError, err.Error()))
		return
	}

	received := types.NewDomainEvent(
		services.WebhookReceivedEventName,
		id.UUID(),
		"", // ownerID resolved downstream by the pixel handler
		services.WebhookReceivedPayload{
			Platform:        enums.WebhookPlatform(platform),
			Event:           wire.SyncEventNameEXTERNAL_PIXEL_EVENT_RECORDED,
			IntegrationID:   storeIntegrationID,
			StoreID:         "", // never trusted from the client; resolved server-side
			ExternalEventID: externalEventID,
			RawBody:         string(body),
		},
	)

	if err := c.events.Save(r.Context(), received); err != nil {
		httputil.RespondError(w, err)
		return
	}

	httputil.RespondJSON(w, http.StatusAccepted, WebhookAcceptedResponse{
		Status:          "accepted",
		ExternalEventID: externalEventID,
		Event:           wire.SyncEventNameEXTERNAL_PIXEL_EVENT_RECORDED,
	})
}

