package controllers

import (
	"bytes"
	"context"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"testing"

	wire "template/contracts-go/wire"
	"template/api-go/internal/sync/enums"
	"template/api-go/internal/webhooks/services"
	"template/core-go/types"
)

// fakeVerifier is a test double implementing services.WebhookVerifier.
type fakeVerifier struct{ valid bool }

func (f fakeVerifier) Platform() enums.WebhookPlatform             { return enums.WebhookPlatformShopify }
func (f fakeVerifier) SignatureHeader() string                      { return "X-Sig" }
func (f fakeVerifier) Verify(_ []byte, _ string) (bool, error)     { return f.valid, nil }

// fakeEventRepo records domain events saved to it.
type fakeEventRepo struct{ saved []types.DomainEventI }

func (r *fakeEventRepo) Save(_ context.Context, e types.DomainEventI) error {
	r.saved = append(r.saved, e)
	return nil
}
func (r *fakeEventRepo) SaveAll(_ context.Context, es []types.DomainEventI) error {
	r.saved = append(r.saved, es...)
	return nil
}

func buildController(valid bool) (*WebhookController, *fakeEventRepo) {
	repo := &fakeEventRepo{}
	factory := services.NewWebhookVerifierFactory([]services.WebhookVerifier{
		fakeVerifier{valid: valid},
	})
	ctrl := NewWebhookController(factory, repo)
	return ctrl, repo
}

func fireRequest(ctrl *WebhookController, query string, body string) *httptest.ResponseRecorder {
	req := httptest.NewRequest(http.MethodPost, "/webhooks?"+query, bytes.NewBufferString(body))
	w := httptest.NewRecorder()
	ctrl.Handle(w, req)
	return w
}

// TestWebhookController_MissingPlatform — missing platform → 400, no save
func TestWebhookController_MissingPlatform(t *testing.T) {
	ctrl, repo := buildController(true)
	w := fireRequest(ctrl, "event=sync.external_order_updated&integrationId=int-1&storeId=store-1", "{}")
	if w.Code != http.StatusBadRequest {
		t.Errorf("status = %d, want 400", w.Code)
	}
	if len(repo.saved) != 0 {
		t.Errorf("saved = %d, want 0", len(repo.saved))
	}
}

