		t.Errorf("entity id not deterministic: %v != %v", evt.EntityID, evt2.EntityID)
	}
}

// TestWebhook_PixelEvent_Accepted — event=sync.external_pixel_event_recorded, no
// signature, returns 202 + saves a WebhookReceivedEvent with that event.
func TestWebhook_PixelEvent_Accepted(t *testing.T) {
	ctrl, repo := buildController(false) // verifier returns !valid — must be bypassed for pixel
	w := fireRequest(ctrl, "event=sync.external_pixel_event_recorded&platform=SHOPIFY&storeIntegrationId=si-1", `{"name":"page_viewed","id":"e1"}`)
	if w.Code != http.StatusAccepted {
		t.Fatalf("status = %d, want 202", w.Code)
	}
	if len(repo.saved) != 1 {
		t.Fatalf("saved = %d, want 1", len(repo.saved))
	}
	evt, ok := repo.saved[0].(services.WebhookReceivedEvent)
	if !ok {
		t.Fatalf("type = %T", repo.saved[0])
	}
	if evt.Payload.Event != wire.SyncEventNameEXTERNAL_PIXEL_EVENT_RECORDED {
		t.Errorf("Event = %q", evt.Payload.Event)
	}
	if evt.Payload.IntegrationID != "si-1" {
		t.Errorf("IntegrationID = %q, want si-1", evt.Payload.IntegrationID)
	}
}

// TestWebhook_PixelEvent_MissingStoreIntegrationId — 400, no save.
func TestWebhook_PixelEvent_MissingStoreIntegrationId(t *testing.T) {
	ctrl, repo := buildController(true)
	w := fireRequest(ctrl, "event=sync.external_pixel_event_recorded&platform=SHOPIFY", `{"name":"page_viewed","id":"e1"}`)
	if w.Code != http.StatusBadRequest {
		t.Errorf("status = %d, want 400", w.Code)
	}
	if len(repo.saved) != 0 {
		t.Errorf("saved = %d, want 0", len(repo.saved))
	}
}

// TestWebhook_PixelEvent_MissingPlatform — 400, no save.
func TestWebhook_PixelEvent_MissingPlatform(t *testing.T) {
	ctrl, repo := buildController(true)
	w := fireRequest(ctrl, "type=PIXEL_EVENT&storeIntegrationId=si-1", `{"name":"page_viewed","id":"e1"}`)
	if w.Code != http.StatusBadRequest {
		t.Errorf("status = %d, want 400", w.Code)
	}
	if len(repo.saved) != 0 {
		t.Errorf("saved = %d, want 0", len(repo.saved))
	}
}

// TestWebhookController_Verified_ResponseShape — 202 response JSON carries externalEventId + event
func TestWebhookController_Verified_ResponseShape(t *testing.T) {
	ctrl, _ := buildController(true)
	w := fireRequest(ctrl, "platform=SHOPIFY&event=sync.external_order_updated&integrationId=int-1&storeId=store-1", `{"x":1}`)
	if w.Code != http.StatusAccepted {
		t.Fatalf("status = %d, want 202", w.Code)
	}
	var resp map[string]any
	if err := json.NewDecoder(w.Body).Decode(&resp); err != nil {
		t.Fatalf("decode response: %v", err)
	}
	if resp["status"] != "accepted" {
		t.Errorf("status field = %v, want accepted", resp["status"])
	}
	if resp["externalEventId"] == "" {
		t.Error("externalEventId must be non-empty in response")
	}
	if resp["event"] != string(wire.SyncEventNameEXTERNAL_ORDER_UPDATED) {
		t.Errorf("event field = %v, want %q", resp["event"], wire.SyncEventNameEXTERNAL_ORDER_UPDATED)
	}
}

